// Re-query y stepper after x update re-render
const yStepperInputRefreshed = page.locator(`${panel} input[id="semio.sketchpad.app.design.panel.details.section.connection.y"]`).first();
await expect(yStepperInputRefreshed).toBeVisible();
const yValueBefore = await yStepperInputRefreshed.inputValue();
console.log(`[DEBUG] [Design] Y stepper value before fill: "${yValueBefore}"`);
// Focus the input directly, select all, then type the new value
await yStepperInputRefreshed.focus();
await page.waitForTimeout(300);
await page.keyboard.press("Control+a");
await page.waitForTimeout(100);
await page.keyboard.type(String(testYValue), { delay: 50 });
await page.waitForTimeout(300);
const yValueAfterType = await yStepperInputRefreshed.inputValue();
console.log(`[DEBUG] [Design] Y stepper value after type: "${yValueAfterType}"`);
// If type didn't work, try fill directly
if (yValueAfterType === "" || yValueAfterType === yValueBefore) {
  console.log(`[DEBUG] [Design] Y keyboard type failed, trying fill()`);
  await yStepperInputRefreshed.fill(String(testYValue));
  const yValueAfterFill = await yStepperInputRefreshed.inputValue();
  console.log(`[DEBUG] [Design] Y stepper value after fill: "${yValueAfterFill}"`);
}
await page.keyboard.press("Enter");
await page.waitForTimeout(2000);

